   159→//
   160→// Guard agains alignment problems in the packed data structures:
   161→// - header length (12 bytes) is a multiple of 4 bytes
   162→// - in all structs, place 16-bit data on 16-bit boundaries,
   163→//   and 32/64 bit data on 32-bit boundaries.
   164→// The easiest way to achieve this is to order the data in
   165→// the structs: 64-bit first, then 32-bit, 16-bit and 8-bit
   166→// data.
   167→// The only exception is the header which must begin with the
   168→// sync bytes.
   169→//
   170→typedef struct __attribute__((__packed__)) _header {
   171→  uint8_t sync[4];           // 4 bytes
   172→  uint16_t data_type;        // 2 bytes
   173→  //
   174→  // two bytes and two shorts that can be used
   175→  // to store data for commands that need that little,
   176→  // so these commands only need the header
   177→  //
   178→  uint8_t b1;                // 1 byte
   179→  uint8_t b2;                // 1 byte
   180→  uint16_t s1;               // 2 bytes
   181→  uint16_t s2;               // 2 bytes
   182→} HEADER;
