  1017→// htonll and friends are macros, and this may have
  1018→// side effects. Better use functions that operate
  1019→// on simple variables (not expressions).
  1020→// Futhermore, explicit casting is done here once for all
  1021→//
  1022→
  1023→static inline uint64_t to_double(double x) {
  1024→  //
  1025→  // The uint64 range encompasses 0 ... 1.8E19
  1026→  //
  1027→  // With a resolution of 1E-10, we map doubles
  1028→  // in the range +/- 9E8 onto that range. For example,
  1029→  // 123456789.123456789 becomes 10234567891234567890 (1.02E19),
  1030→  // 0.0 becomes 9000000000000000000 (9E18),
  1031→  // and -123456789.123456789 becomes 7765432108765432110 (7.76E18)
  1032→  //
  1033→  uint64_t u64 = (x + 9.0E8) * 1.0E10;
  1034→#ifdef __APPLE__
  1035→  uint64_t ret = htonll(u64);
  1036→#else
  1037→  uint64_t ret = htobe64(u64);
  1038→#endif
  1039→  return ret;
  1040→}
  1041→
  1042→static inline uint64_t to_64(long long x) {
