  1051→static inline uint32_t to_32(int x) {
  1052→  int32_t s32 = x;
  1053→  uint32_t ret = htonl(s32);
  1054→  return ret;
  1055→}
  1056→
  1057→static inline uint16_t to_16(int x) {
  1058→  int16_t s16 = x;
  1059→  uint16_t ret = htons(s16);
  1060→  return ret;
  1061→}
  1062→
  1063→static inline double from_double(uint64_t y) {
  1064→#ifdef __APPLE__
  1065→  uint64_t u64 = ntohll(y);
  1066→#else
  1067→  uint64_t u64 = be64toh(y);
  1068→#endif
  1069→  return (1.0E-10 * (double) u64 - 9.0E8);
  1070→}
  1071→
  1072→static inline long long from_64(uint64_t y) {
  1073→#ifdef __APPLE__
  1074→  uint64_t u64 = ntohll(y);
  1075→#else
  1076→  uint64_t u64 = be64toh(y);
  1077→#endif
  1078→  return (long long) u64;
  1079→}
