  1091→static const uint8_t syncbytes[4] = { 0xFA, 0xFA, 0xAF, 0xAF };
  1092→
  1093→static inline void SYNC(uint8_t *sync) {
  1094→  *sync++ = 0xFA;
  1095→  *sync++ = 0xFA;
  1096→  *sync++ = 0xAF;
  1097→  *sync++ = 0xAF;
  1098→}
  1099→#endif
