  ritEnabled: false,
  xit: 0,
  xitEnabled: false,
  band: 0,
  step: 100,
});

// Receiver state
export const receiver = writable({
  id: 0,
  volume: 0.5,
  agc: 3,
  squelch: 0,
  squelchEnabled: false,
  zoom: 1,
  pan: 0,
  nb: 0,
  nr: 0,
  anf: false,
  filterLow: -2850,
  filterHigh: -150,
});

// Transmitter state
export const transmitter = writable({
  drive: 50,
  puresignal: false,
});

// Meter readings
export const meters = writable({
  sMeter: -127,
  fwd: 0,
  swr: 1,
  alc: 0,
});

// Spectrum data (array of dBm values)
export const spectrum = writable([]);
export const spectrumWidth = writable(0);

// TX state
export const mox = writable(false);
export const tune = writable(false);

// Active VFO
export const activeVfo = writable(0); // 0 = A, 1 = B

// Derived store for current VFO
export const currentVfo = derived(
  [activeVfo, vfoA, vfoB],
  ([$activeVfo, $vfoA, $vfoB]) => $activeVfo === 0 ? $vfoA : $vfoB
);

// Mode names
export const MODE_NAMES = [
  'LSB', 'USB', 'DSB', 'CWL', 'CWU', 'FMN', 'AM', 'DIGU', 'SPEC', 'DIGL', 'SAM', 'DRM'
];

// Helper to format frequency
export function formatFrequency(hz) {
  const mhz = hz / 1000000;
  return mhz.toFixed(6).replace(/(\d)(?=(\d{3})+\.)/g, '$1,');
}

// Helper to format S-meter
export function formatSMeter(dbm) {
  if (dbm < -121) return 'S0';
  if (dbm < -115) return 'S1';
  if (dbm < -109) return 'S2';
  if (dbm < -103) return 'S3';
  if (dbm < -97) return 'S4';
  if (dbm < -91) return 'S5';
  if (dbm < -85) return 'S6';
  if (dbm < -79) return 'S7';
  if (dbm < -73) return 'S8';
  if (dbm < -63) return 'S9';
  const over = Math.round((dbm + 73) / 6) * 10;
  return `S9+${over}`;
}

