/**
 * WebSocket connection manager
 */
import {
  connected,
  connectionError,
  radio,
  vfoA,
  vfoB,
  receiver,
  transmitter,
  meters,
  spectrum,
  spectrumWidth,
  mox,
  tune,
  MODE_NAMES,
} from './stores.js';

let ws = null;
let reconnectTimer = null;
let heartbeatTimer = null;
const RECONNECT_DELAY = 3000;
const HEARTBEAT_INTERVAL = 10000;

/**
 * Connect to WebSocket server
 */
export function connect(url = null) {
  if (ws && ws.readyState === WebSocket.OPEN) {
    return;
  }

  // Default URL based on current location
  if (!url) {
    const protocol = window.location.protocol === 'https:' ? 'wss:' : 'ws:';
    const host = window.location.hostname;
    const port = 8080; // Gateway WebSocket port
    url = `${protocol}//${host}:${port}`;
  }

  console.log(`Connecting to ${url}`);
  connectionError.set(null);

  try {
    ws = new WebSocket(url);
    ws.binaryType = 'arraybuffer';

    ws.onopen = handleOpen;
    ws.onclose = handleClose;
    ws.onerror = handleError;
    ws.onmessage = handleMessage;
  } catch (e) {
    console.error('WebSocket connection error:', e);
    connectionError.set(e.message);
    scheduleReconnect();
  }
}

/**
 * Disconnect from WebSocket server
 */
export function disconnect() {
  if (reconnectTimer) {
    clearTimeout(reconnectTimer);
    reconnectTimer = null;
  }
  if (heartbeatTimer) {
    clearInterval(heartbeatTimer);
    heartbeatTimer = null;
  }
  if (ws) {
    ws.close();
    ws = null;
  }
  connected.set(false);
}

/**
 * Send command to server
 */
export function sendCommand(cmd) {
  if (ws && ws.readyState === WebSocket.OPEN) {
    ws.send(JSON.stringify(cmd));
  } else {
    console.warn('Cannot send: not connected');
  }
}

// Command helpers
export function setFrequency(vfo, hz) {
  sendCommand({ cmd: 'freq', vfo, hz });
}

export function setMode(vfo, mode) {
  sendCommand({ cmd: 'mode', vfo, mode });
}

export function setFilter(vfo, filter) {
  sendCommand({ cmd: 'filter', vfo, filter });
}

export function setVolume(id, value) {
  sendCommand({ cmd: 'volume', id, value });
}

export function setAgc(id, agc) {
  sendCommand({ cmd: 'agc', id, agc });
}

export function setZoom(id, level) {
  sendCommand({ cmd: 'zoom', id, level });
}

export function stepVfo(vfo, steps) {
  sendCommand({ cmd: 'step', vfo, steps });
}

export function toggleMox() {
  let currentMox;
  mox.subscribe(v => currentMox = v)();
  sendCommand({ cmd: 'mox', state: currentMox ? 0 : 1 });
}

export function setMox(state) {
  sendCommand({ cmd: 'mox', state: state ? 1 : 0 });
}

// Internal handlers

function handleOpen() {
  console.log('WebSocket connected');
  connected.set(true);
  connectionError.set(null);

  // Start heartbeat
  heartbeatTimer = setInterval(() => {
    sendCommand({ cmd: 'heartbeat' });
  }, HEARTBEAT_INTERVAL);

  // Request spectrum
  sendCommand({ cmd: 'rx_spectrum', id: 0, enable: true });
}

function handleClose(event) {
  console.log('WebSocket closed:', event.code, event.reason);
  connected.set(false);
  ws = null;

  if (heartbeatTimer) {
    clearInterval(heartbeatTimer);
    heartbeatTimer = null;
  }

  // Auto reconnect
  scheduleReconnect();
}

function handleError(event) {
  console.error('WebSocket error:', event);
  connectionError.set('Connection error');
}

function handleMessage(event) {
  if (event.data instanceof ArrayBuffer) {
    handleBinaryMessage(event.data);
  } else {
    handleJsonMessage(event.data);
  }
}

function handleBinaryMessage(data) {
  const view = new DataView(data);
  const msgType = view.getUint8(0);

  if (msgType === 0x01) {
    // Spectrum data
    const rxId = view.getUint8(1);
    const width = view.getUint16(2, false); // big-endian

    const spectrumData = [];
    for (let i = 0; i < width; i++) {
      spectrumData.push(view.getFloat32(4 + i * 4, false));
    }

    spectrum.set(spectrumData);
    spectrumWidth.set(width);

  } else if (msgType === 0x02) {
    // Audio data
    const rxId = view.getUint8(1);
    const numSamples = view.getUint16(2, false);

    const samples = new Int16Array(numSamples);
    for (let i = 0; i < numSamples; i++) {
      samples[i] = view.getInt16(4 + i * 2, false);
    }

    // Audio playback handled by audioPlayer.js
    if (window.audioPlayer) {
      window.audioPlayer.addSamples(samples);
    }
  }
}

function handleJsonMessage(data) {
  try {
    const msg = JSON.parse(data);
    const type = msg.type;

    switch (type) {
      case 'vfo':
        updateVfo(msg);
        break;

      case 'receiver':
        updateReceiver(msg);
        break;

      case 'transmitter':
        updateTransmitter(msg);
        break;

      case 'radio':
        updateRadio(msg);
        break;

      case 'meter':
        updateMeters(msg);
        break;

      case 'mox':
        mox.set(msg.state);
        break;

      case 'tune':
        tune.set(msg.state);
        break;

      case 'start_radio':
        console.log('Radio started');
        break;

      case 'heartbeat_ack':
        // Heartbeat acknowledged
        break;

      default:
        console.debug('Unknown message type:', type);
    }
  } catch (e) {
    console.error('JSON parse error:', e, data);
  }
}

function updateVfo(msg) {
  const vfoData = {
    frequency: msg.frequency,
    mode: msg.mode,
    modeName: MODE_NAMES[msg.mode] || String(msg.mode),
    filter: msg.filter,
    ctun: msg.ctun,
    rit: msg.rit,
    ritEnabled: msg.rit_enabled,
    xit: msg.xit,
    xitEnabled: msg.xit_enabled,
    band: msg.band,
    step: msg.step,
  };

  if (msg.id === 0) {
    vfoA.set(vfoData);
  } else {
    vfoB.set(vfoData);
  }
}

function updateReceiver(msg) {
  receiver.set({
    id: msg.id,
    volume: msg.volume,
    agc: msg.agc,
    squelch: msg.squelch,
    squelchEnabled: msg.squelch_enabled,
    zoom: msg.zoom,
    pan: msg.pan,
    nb: msg.nb,
    nr: msg.nr,
    anf: msg.anf,
    filterLow: msg.filter_low,
    filterHigh: msg.filter_high,
  });
}

function updateTransmitter(msg) {
  transmitter.set({
    drive: msg.drive,
    puresignal: msg.puresignal,
  });
}

function updateRadio(msg) {
  radio.set({
    name: msg.name,
    receivers: msg.receivers,
    locked: msg.locked,
  });
}

function updateMeters(msg) {
  meters.set({
    sMeter: msg.s_meter,
    fwd: msg.fwd,
    swr: msg.swr,
    alc: msg.alc,
  });

  // Also update VFO frequencies from meter data for quick updates
  if (msg.vfo_a_freq) {
    vfoA.update(v => ({ ...v, frequency: msg.vfo_a_freq }));
  }
  if (msg.vfo_b_freq) {
    vfoB.update(v => ({ ...v, frequency: msg.vfo_b_freq }));
  }
}

function scheduleReconnect() {
  if (reconnectTimer) return;

  console.log(`Reconnecting in ${RECONNECT_DELAY}ms...`);
  reconnectTimer = setTimeout(() => {
    reconnectTimer = null;
    connect();
  }, RECONNECT_DELAY);
}

