/**
 * Audio Player using Web Audio API
 *
 * Handles audio playback with buffering for network jitter.
 */

class AudioPlayer {
  constructor() {
    this.audioContext = null;
    this.sampleRate = 48000; // piHPSDR sends 48kHz
    this.bufferSize = 4096;
    this.buffer = [];
    this.isPlaying = false;
    this.scriptNode = null;
    this.gainNode = null;
    this.volume = 0.5;

    // Buffer management
    this.minBuffer = 2; // Minimum buffers before starting playback
    this.maxBuffer = 10; // Maximum buffers to keep
  }

  /**
   * Initialize audio context (must be called from user interaction)
   */
  async init() {
    if (this.audioContext) return;

    try {
      this.audioContext = new (window.AudioContext || window.webkitAudioContext)({
        sampleRate: this.sampleRate,
      });

      // Create gain node for volume control
      this.gainNode = this.audioContext.createGain();
      this.gainNode.gain.value = this.volume;
      this.gainNode.connect(this.audioContext.destination);

      // Create script processor for custom audio generation
      this.scriptNode = this.audioContext.createScriptProcessor(this.bufferSize, 0, 2);
      this.scriptNode.onaudioprocess = this.processAudio.bind(this);
      this.scriptNode.connect(this.gainNode);

      console.log('Audio initialized:', this.audioContext.sampleRate, 'Hz');
    } catch (e) {
      console.error('Failed to initialize audio:', e);
    }
  }

  /**
   * Add samples to the buffer
   */
  addSamples(samples) {
    if (!this.audioContext) return;

    // Convert Int16 samples to Float32 (-1.0 to 1.0)
    const floatSamples = new Float32Array(samples.length);
    for (let i = 0; i < samples.length; i++) {
      floatSamples[i] = samples[i] / 32768.0;
    }

    this.buffer.push(floatSamples);

    // Prevent buffer overflow
    while (this.buffer.length > this.maxBuffer) {
      this.buffer.shift();
    }

    // Start playback when we have enough buffer
    if (!this.isPlaying && this.buffer.length >= this.minBuffer) {
      this.start();
    }
  }

  /**
   * Process audio callback
   */
  processAudio(event) {
    const outputL = event.outputBuffer.getChannelData(0);
    const outputR = event.outputBuffer.getChannelData(1);

    let outIndex = 0;

    while (outIndex < this.bufferSize && this.buffer.length > 0) {
      const samples = this.buffer[0];
      const remaining = this.bufferSize - outIndex;
      const toCopy = Math.min(samples.length, remaining);

      // Audio from piHPSDR is stereo interleaved
      for (let i = 0; i < toCopy && i < samples.length; i += 2) {
        if (outIndex < this.bufferSize) {
          outputL[outIndex] = samples[i] || 0;
          outputR[outIndex] = samples[i + 1] || samples[i] || 0;
          outIndex++;
        }
      }

      this.buffer.shift();
    }

    // Fill remaining with silence
    while (outIndex < this.bufferSize) {
      outputL[outIndex] = 0;
      outputR[outIndex] = 0;
      outIndex++;
    }

    // Stop if buffer empty
    if (this.buffer.length === 0) {
      // Don't stop immediately, wait for more data
    }
  }

  /**
   * Start audio playback
   */
  start() {
    if (this.isPlaying || !this.audioContext) return;

    if (this.audioContext.state === 'suspended') {
      this.audioContext.resume();
    }

    this.isPlaying = true;
    console.log('Audio started');
  }

  /**
   * Stop audio playback
   */
  stop() {
    this.isPlaying = false;
    this.buffer = [];
    console.log('Audio stopped');
  }

  /**
   * Set volume (0.0 to 1.0)
   */
  setVolume(value) {
    this.volume = Math.max(0, Math.min(1, value));
    if (this.gainNode) {
      this.gainNode.gain.value = this.volume;
    }
  }

  /**
   * Get current buffer level (for UI)
   */
  getBufferLevel() {
    return this.buffer.length;
  }

  /**
   * Check if audio is available
   */
  isAvailable() {
    return !!(window.AudioContext || window.webkitAudioContext);
  }
}

// Global instance
const audioPlayer = new AudioPlayer();
window.audioPlayer = audioPlayer;

export default audioPlayer;

